=== FILE: skid_buffer.v ===
// skid_buffer: two-register valid/ready register slice.
// Implements interface_spec.md and microarchitecture.md (rtl/skid-buffer).
// Every output is a flop or the inverse of one; inputs reach only next state.
module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    // Skid register: holds the newer of two beats.
    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // Next-state values.
    reg             m_valid_nxt;
    reg [WIDTH-1:0] m_data_nxt;
    reg             skid_valid_nxt;
    reg [WIDTH-1:0] skid_data_nxt;

    wire m_free;  // output register may load on this edge
    wire s_fire;  // upstream transfer on this edge

    assign s_ready = !skid_valid;
    assign m_free  = !m_valid || m_ready;
    assign s_fire  = s_valid && s_ready;

    // Next state, per the microarchitecture section 3 table.
    always @(*) begin
        m_valid_nxt    = m_valid;
        m_data_nxt     = m_data;
        skid_valid_nxt = skid_valid;
        skid_data_nxt  = skid_data;
        if (m_free) begin
            if (skid_valid) begin
                // Skid beat moves to the output register.
                m_valid_nxt    = 1'b1;
                m_data_nxt     = skid_data;
                skid_valid_nxt = 1'b0;
            end else begin
                // Output register loads straight from the input.
                m_valid_nxt = s_valid;
                m_data_nxt  = s_data;
            end
        end else if (s_fire) begin
            // Output stalled: the accepted beat goes to the skid register.
            skid_valid_nxt = 1'b1;
            skid_data_nxt  = s_data;
        end
    end

    // Control registers: synchronous, active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_nxt;
            skid_valid <= skid_valid_nxt;
        end
    end

    // Data registers: no reset (microarchitecture section 2); they load only
    // in their control's rows, so a stalled beat never changes.
    always @(posedge clk) begin
        m_data    <= m_data_nxt;
        skid_data <= skid_data_nxt;
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Only assumption: reset is active on the first cycle.
    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    // Reference queue of up to two beats, moved only by port handshakes.
    reg [1:0]       f_count;
    reg [WIDTH-1:0] f_q0;  // oldest
    reg [WIDTH-1:0] f_q1;  // newer
    wire f_push = s_valid && s_ready;
    wire f_pop  = m_valid && m_ready;

    always @(posedge clk) begin
        if (!rst_n) begin
            f_count <= 2'd0;
        end else begin
            case ({f_push, f_pop})
                2'b10: begin
                    if (f_count == 2'd0) f_q0 <= s_data;
                    else                 f_q1 <= s_data;
                    f_count <= f_count + 2'd1;
                end
                2'b01: begin
                    f_q0    <= f_q1;
                    f_count <= f_count - 2'd1;
                end
                2'b11: begin
                    if (f_count == 2'd1) begin
                        f_q0 <= s_data;
                    end else begin
                        f_q0 <= f_q1;
                        f_q1 <= s_data;
                    end
                end
                default: begin
                end
            endcase
        end
    end

    // Ports and internal state agree with the queue.
    always @(*) begin
        if (f_past_valid) begin
            assert(f_count != 2'd3);
            assert(m_valid == (f_count != 2'd0));
            assert(skid_valid == (f_count == 2'd2));
            assert(s_ready == (f_count != 2'd2));
            if (m_valid) assert(m_data == f_q0);
            if (skid_valid) assert(skid_data == f_q1);
        end
    end

    // Reset result and the hold rule.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert(!m_valid);
                assert(s_ready);
            end else if ($past(m_valid) && !$past(m_ready)) begin
                assert(m_valid);
                assert(m_data == $past(m_data));
            end
        end
    end

    // Cover helpers.
    reg       f_was_full;
    reg [1:0] f_tp;
    always @(posedge clk) begin
        if (!rst_n) begin
            f_was_full <= 1'b0;
            f_tp       <= 2'd0;
        end else begin
            if (skid_valid) f_was_full <= 1'b1;
            if (f_push && f_pop) begin
                if (f_tp != 2'd3) f_tp <= f_tp + 2'd1;
            end else begin
                f_tp <= 2'd0;
            end
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover(m_valid && !m_ready);      // a stall
            cover(skid_valid);               // a full slice
            cover(f_was_full && !m_valid);   // a drain after full
            cover(f_tp == 2'd3);             // full throughput, 3 edges
        end
    end
`endif

endmodule
=== END FILE ===
