`timescale 1ns/1ps

// Self-checking testbench for skid_buffer, lanes at WIDTH 8 and WIDTH 1.
// Both instances share the handshakes; the WIDTH 1 lane carries bit 0.
module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg        m_ready;
    reg  [7:0] s_data;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready8), .s_data(s_data),
        .m_valid(m_valid8), .m_ready(m_ready), .m_data(m_data8));

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready1), .s_data(s_data[0:0]),
        .m_valid(m_valid1), .m_ready(m_ready), .m_data(m_data1));

    integer passed;
    integer failed;
    integer n_in;
    integer n_out;
    integer n_drop;
    integer cov_full;
    integer cov_stall;
    integer cov_tp;
    integer cov_reset;
    integer ok;
    integer i;
    integer k;
    integer ph;
    integer rs;
    integer rr;
    integer s_thr;
    integer m_thr;
    integer n0;
    integer o0;
    integer t0;

    // Reference model: up to two beats, oldest in e_q0.
    reg        model_ok;
    reg  [1:0] e_cnt;
    reg  [7:0] e_q0;
    reg  [7:0] e_q1;

    reg        prev_stall;
    reg  [7:0] prev_data8;
    reg  [0:0] prev_data1;

    reg        st_push;
    reg        st_pop;
    reg        st_stall;
    reg  [7:0] st_d8;
    reg  [0:0] st_d1;
    reg  [7:0] st_sd;

    reg        g_sr8;
    reg        g_sr1;
    reg        g_mv8;
    reg        g_mv1;
    reg  [7:0] g_md8;
    reg  [0:0] g_md1;

    reg  [8*64-1:0] nonce;

    wire exp_m_valid = (e_cnt != 2'd0);
    wire exp_s_ready = (e_cnt != 2'd2);

    task chk(input cond, input integer id);
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("skid_buffer_tb: check %0d failed at time %0t", id, $time);
            end
        end
    endtask

    // Outputs against the model, plus the hold rule.
    task check_outputs;
        begin
            chk(m_valid8 == exp_m_valid, 1);
            chk(s_ready8 == exp_s_ready, 2);
            chk(m_valid1 == exp_m_valid, 3);
            chk(s_ready1 == exp_s_ready, 4);
            if (exp_m_valid) begin
                chk(m_data8 == e_q0, 5);
                chk(m_data1 == e_q0[0:0], 6);
            end
            if (prev_stall) begin
                chk(m_valid8 && (m_data8 == prev_data8), 7);
                chk(m_valid1 && (m_data1 == prev_data1), 8);
            end
        end
    endtask

    // Outputs must not move with the inputs inside a cycle.
    task glitch_check;
        begin
            g_sr8 = s_ready8;
            g_sr1 = s_ready1;
            g_mv8 = m_valid8;
            g_mv1 = m_valid1;
            g_md8 = m_data8;
            g_md1 = m_data1;
            m_ready = ~m_ready;
            s_valid = ~s_valid;
            s_data  = ~s_data;
            #1;
            chk(s_ready8 === g_sr8, 9);
            chk(s_ready1 === g_sr1, 10);
            chk(m_valid8 === g_mv8, 11);
            chk(m_valid1 === g_mv1, 12);
            chk(m_data8 === g_md8, 13);
            chk(m_data1 === g_md1, 14);
            m_ready = ~m_ready;
            s_valid = ~s_valid;
            s_data  = ~s_data;
            #1;
        end
    endtask

    // One clock cycle: check, glitch-check, edge, model update.
    task step;
        begin
            #2;
            if (model_ok) check_outputs;
            glitch_check;
            st_push  = model_ok && rst_n && s_valid && exp_s_ready;
            st_pop   = model_ok && rst_n && exp_m_valid && m_ready;
            st_stall = model_ok && rst_n && exp_m_valid && !m_ready;
            st_d8    = m_data8;
            st_d1    = m_data1;
            st_sd    = s_data;
            if (st_stall) cov_stall = cov_stall + 1;
            if (st_push && st_pop) cov_tp = cov_tp + 1;
            clk = 1'b1;
            #1;
            if (!rst_n) begin
                if (model_ok) begin
                    n_drop = n_drop + {30'd0, e_cnt};
                    if (e_cnt != 2'd0) cov_reset = cov_reset + 1;
                end
                e_cnt    = 2'd0;
                model_ok = 1'b1;
            end else begin
                if (st_push) n_in = n_in + 1;
                if (st_pop) n_out = n_out + 1;
                case ({st_push, st_pop})
                    2'b10: begin
                        if (e_cnt == 2'd0) e_q0 = st_sd;
                        else               e_q1 = st_sd;
                        e_cnt = e_cnt + 2'd1;
                    end
                    2'b01: begin
                        e_q0  = e_q1;
                        e_cnt = e_cnt - 2'd1;
                    end
                    2'b11: begin
                        if (e_cnt == 2'd1) begin
                            e_q0 = st_sd;
                        end else begin
                            e_q0 = e_q1;
                            e_q1 = st_sd;
                        end
                    end
                    default: begin
                    end
                endcase
            end
            if (e_cnt == 2'd2) cov_full = cov_full + 1;
            prev_stall = st_stall;
            prev_data8 = st_d8;
            prev_data1 = st_d1;
            #4;
            clk = 1'b0;
        end
    endtask

    initial begin
        passed     = 0;
        failed     = 0;
        n_in       = 0;
        n_out      = 0;
        n_drop     = 0;
        cov_full   = 0;
        cov_stall  = 0;
        cov_tp     = 0;
        cov_reset  = 0;
        ok         = 0;
        model_ok   = 1'b0;
        e_cnt      = 2'd0;
        e_q0       = 8'h00;
        e_q1       = 8'h00;
        prev_stall = 1'b0;
        prev_data8 = 8'h00;
        prev_data1 = 1'b0;
        nonce      = {(8*64){1'b0}};
        clk        = 1'b0;
        rst_n      = 1'b0;
        s_valid    = 1'b0;
        m_ready    = 1'b0;
        s_data     = 8'h00;

        // T1: reset values (sender active during reset).
        s_valid = 1'b1;
        s_data  = 8'h3C;
        step;
        step;
        chk(!m_valid8 && s_ready8 && !m_valid1 && s_ready1, 20);
        rst_n   = 1'b1;
        s_valid = 1'b0;

        // T2: one-cycle latency.
        s_valid = 1'b1;
        s_data  = 8'hA5;
        m_ready = 1'b1;
        #1;
        chk(!m_valid8 && !m_valid1, 30);
        step;
        chk(m_valid8 && (m_data8 == 8'hA5), 31);
        chk(m_valid1 && (m_data1 == 1'b1), 32);
        s_valid = 1'b0;
        step;
        chk(!m_valid8 && !m_valid1, 33);

        // T3: full throughput, 64 beats back to back.
        t0 = cov_tp;
        m_ready = 1'b1;
        for (i = 0; i < 64; i = i + 1) begin
            s_valid = 1'b1;
            s_data  = i[7:0];
            step;
            chk(s_ready8 && s_ready1, 40);
            chk(m_valid8 && (m_data8 == i[7:0]), 41);
        end
        chk((cov_tp - t0) == 63, 42);
        s_valid = 1'b0;
        step;
        chk(!m_valid8 && !m_valid1, 43);

        // T4: stall with one held (second accepted), two held (third refused).
        n0 = n_in;
        o0 = n_out;
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data  = 8'h11;
        step;
        chk(m_valid8 && (m_data8 == 8'h11), 50);
        chk(s_ready8 && s_ready1, 51);
        s_data = 8'h22;
        step;
        chk(!s_ready8 && !s_ready1, 52);
        chk(m_valid8 && (m_data8 == 8'h11), 53);
        s_data = 8'h99;
        step;
        chk(!s_ready8 && (m_data8 == 8'h11), 55);
        s_data = 8'h77;
        step;
        chk(!s_ready8 && (m_data8 == 8'h11), 55);
        s_data = 8'h33;
        step;
        chk(!s_ready8 && (m_data8 == 8'h11), 55);
        chk((n_in - n0) == 2, 56);
        // Ready rises: beats leave in order, each once.
        m_ready = 1'b1;
        step;
        chk(s_ready8 && s_ready1 && m_valid8 && (m_data8 == 8'h22), 57);
        step;
        chk(m_valid8 && (m_data8 == 8'h33) && (m_data1 == 1'b1), 58);
        s_valid = 1'b0;
        step;
        chk(!m_valid8 && s_ready8 && !m_valid1 && s_ready1, 59);
        chk((n_out - o0) == 3, 60);
        chk((n_in - n0) == 3, 60);

        // T5: reset with two beats held.
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data  = 8'h44;
        step;
        s_data = 8'h55;
        step;
        chk(!s_ready8 && m_valid8, 61);
        rst_n = 1'b0;
        step;
        chk(!m_valid8 && s_ready8 && !m_valid1 && s_ready1, 62);
        rst_n   = 1'b1;
        s_valid = 1'b0;
        m_ready = 1'b1;
        step;
        chk(!m_valid8 && !m_valid1, 63);

        // T6: random traffic against the model, with sparse resets.
        for (ph = 0; ph < 8; ph = ph + 1) begin
            case (ph)
                0: begin s_thr = 8;  m_thr = 8;  end
                1: begin s_thr = 16; m_thr = 4;  end
                2: begin s_thr = 4;  m_thr = 16; end
                3: begin s_thr = 16; m_thr = 16; end
                4: begin s_thr = 14; m_thr = 2;  end
                5: begin s_thr = 12; m_thr = 12; end
                6: begin s_thr = 16; m_thr = 1;  end
                default: begin s_thr = 10; m_thr = 6; end
            endcase
            for (k = 0; k < 500; k = k + 1) begin
                rs = $random;
                rr = $random;
                s_valid = ((rs & 15) < s_thr);
                m_ready = ((rr & 15) < m_thr);
                s_data  = rs[15:8];
                rst_n   = (rr[31:22] != 10'd0);
                step;
            end
        end

        // Drain.
        rst_n   = 1'b1;
        s_valid = 1'b0;
        m_ready = 1'b1;
        step;
        step;
        step;
        step;
        chk(!m_valid8 && s_ready8 && !m_valid1 && s_ready1, 70);
        chk(e_cnt == 2'd0, 71);
        chk(n_in == (n_out + n_drop), 72);

        // Coverage goals reached.
        chk(cov_full > 0, 80);
        chk(cov_stall > 0, 81);
        chk(cov_tp > 0, 82);
        chk(cov_reset > 0, 83);
        chk(n_drop > 0, 84);

        ok = $value$plusargs("nirmaan_nonce=%s", nonce);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
